const lastSeenRaw = (($('Get Last Heartbeat').item.json) || {}).lastSeenRaw || null;
const alertActiveRaw = (($('Get Heartbeat Alert State').item.json) || {}).alertActiveRaw || null;
const ALERT_AFTER_MINUTES = 20;
const nowMs = Date.now();
let minutesSince = null;
if (lastSeenRaw) {
  const t = Date.parse(lastSeenRaw);
  if (!isNaN(t)) minutesSince = (nowMs - t) / 60000;
}
const isDown = minutesSince === null || minutesSince > ALERT_AFTER_MINUTES;
const wasAlerted = Boolean(alertActiveRaw);
let decision = 'no_change';
if (isDown && !wasAlerted) decision = 'alert_down';
else if (!isDown && wasAlerted) decision = 'alert_recovered';
return [{ json: { decision, minutes_since: minutesSince, last_seen: lastSeenRaw, is_down: isDown } }];

