const r = $json;
if (r.statusCode !== 200 || !r.body) return [];
const contacts = r.body.contacts || [];
return contacts.map((c) => ({ json: { contact_id: c.id, contact_name: `${c.firstName || ''} ${c.lastName || ''}`.trim() } }));

const calIds = ['YOUR_GHL_STANDARD_CALENDAR_ID', 'YOUR_GHL_EMERGENCY_CALENDAR_ID'];
const source = $('Extract Booked Contacts').item.json;
const contactId = source.contact_id;
const contactName = source.contact_name || '';
const ar = $json;
if (ar.statusCode !== 200 || !ar.body) {
  return { json: { action: 'alert', contact_id: contactId, contact_name: contactName,
    reason: `could not read appointments for contact ${contactId} (HTTP ${ar.statusCode})` } };
}
const events = ar.body.events || [];
const nowMs = Date.now();
const dead = ['cancelled', 'canceled', 'noshow', 'invalid'];
const norm = (a) => String(a.appointmentStatus || a.appoinmentStatus || '').toLowerCase().trim();
const tracked = events.filter((a) => calIds.includes(a.calendarId));
const liveFuture = tracked.find((a) => Date.parse(a.startTime) > nowMs && !dead.includes(norm(a)));
if (liveFuture) return { json: { action: 'none', contact_id: contactId, contact_name: contactName } };

if (!tracked.length) {
  return { json: { action: 'correct', event: 'appt_cancelled', contact_id: contactId, contact_name: contactName,
    appointment_id: '', calendar_id: '', start_time: '', status: 'none', date_updated: new Date().toISOString(),
    reason: 'stage says booked but contact has no appointment at all on our calendars' } };
}

let appt = tracked[0];
for (const a of tracked) if (Date.parse(a.dateUpdated) > Date.parse(appt.dateUpdated)) appt = a;
const status = norm(appt);
const map = { showed: 'appt_showed', completed: 'appt_completed', cancelled: 'appt_cancelled', canceled: 'appt_cancelled',
  noshow: 'appt_noshow', 'no-show': 'appt_noshow', invalid: 'appt_cancelled' };
const event = map[status] || '';
if (!event) {
  return { json: { action: 'alert', contact_id: contactId, contact_name: contactName,
    reason: `most recently updated tracked appointment ${appt.id} is '${status}' with no live future booking -- ambiguous, needs a human look`,
    appointment_id: appt.id || '', status } };
}
return { json: { action: 'correct', event, contact_id: contactId, contact_name: contactName,
  appointment_id: appt.id || '', calendar_id: appt.calendarId || '', start_time: appt.startTime || '',
  status, date_updated: appt.dateUpdated || '' } };

