return [
  { json: { calendar_id: 'YOUR_GHL_STANDARD_CALENDAR_ID', calendar_type: 'standard' } },
  { json: { calendar_id: 'YOUR_GHL_EMERGENCY_CALENDAR_ID', calendar_type: 'emergency' } },
];

const dead = ['cancelled', 'canceled', 'noshow', 'invalid'];
const calList = $('Build Calendar List').all();
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const r = items[i].json;
  const calType = (calList[i] && calList[i].json.calendar_type) || 'unknown';
  if (r.statusCode !== 200 || !r.body) continue;
  const events = r.body.events || [];
  for (const e of events) {
    const status = String(e.appointmentStatus || e.appoinmentStatus || '').toLowerCase().trim();
    if (dead.includes(status)) continue;
    out.push({ json: { id: e.id, contact_id: e.contactId, calendar_id: e.calendarId, calendar_type: calType,
      status, startTime: e.startTime, dateUpdated: e.dateUpdated } });
  }
}
return out;

const stageFieldId = 'YOUR_GHL_FIELD_ID_STAGE';
const evt = $('Flatten Calendar Events').item.json;
const cr = $json;
if (cr.statusCode !== 200 || !cr.body || !cr.body.contact) {
  return { json: { action: 'alert', contact_id: evt.contact_id, appointment_id: evt.id,
    reason: `could not read contact ${evt.contact_id} (HTTP ${cr.statusCode})` } };
}
const fields = cr.body.contact.customFields || [];
const f = fields.find((x) => x.id === stageFieldId);
const stage = String((f ? (f.value !== undefined ? f.value : f.fieldValue) : '') || '').trim().toLowerCase();
const ok = ['booked', 'served'];
if (ok.includes(stage)) return { json: { action: 'none', contact_id: evt.contact_id } };
return { json: { action: 'alert', contact_id: evt.contact_id, appointment_id: evt.id, calendar_type: evt.calendar_type,
  status: evt.status, start_time: evt.startTime, stage,
  reason: `calendar has a real '${evt.status}' appointment but the contact's stage is '${stage || "(blank)"}'` } };

