const rows = $input.all().map((i) => i.json).filter((r) => r && r.key);
const row = rows.find((r) => r.key === 'dormant_after_days');
const n = row ? parseInt(row.value, 10) : NaN;
return [{ json: { dormant_after_days: (Number.isFinite(n) && n > 0) ? n : null } }];

