if (r.statusCode !== 200 || !r.body) return [];
const contacts = r.body.contacts || [];
return contacts.map((c) => ({ json: { contact_id: c.id, contact_name: `${c.firstName || ''} ${c.lastName || ''}`.trim(), stage: 'qualified' } }));

const r = $json;
if (r.statusCode !== 200 || !r.body) return [];
const contacts = r.body.contacts || [];
return contacts.map((c) => ({ json: { contact_id: c.id, contact_name: `${c.firstName || ''} ${c.lastName || ''}`.trim(), stage: 'served' } }));

const cfgRows = $('Aggregate Dormant Sweep Config').all().map((i) => i.json);
const days = cfgRows[0] && cfgRows[0].dormant_after_days;
if (!days) {
  return [{ json: { config_error: true, message: "dormant_after_days missing or invalid in desertcomfort_config - sweep skipped, nobody moved" } }];
}
const ledgerRows = $('Get Ledger Rows For Dormant Sweep').all().map((i) => i.json);
const lastSeen = {};
for (const row of ledgerRows) {
  const cid = row.contact_id;
  if (!cid) continue;
  const t = Date.parse(row.occurred_at);
  if (!Number.isFinite(t)) continue;
  if (!lastSeen[cid] || t > lastSeen[cid]) lastSeen[cid] = t;
}
const candidates = [
  ...$('Extract Lead Contacts For Dormant Sweep').all().map((i) => i.json),
  ...$('Extract Qualified Contacts For Dormant Sweep').all().map((i) => i.json),
  ...$('Extract Served Contacts For Dormant Sweep').all().map((i) => i.json),
];
const cutoff = Date.now() - days * 24 * 3600 * 1000;
const out = [];
for (const c of candidates) {
  const last = lastSeen[c.contact_id];
  if (last === undefined) continue;
  if (last < cutoff) {
    out.push({ json: {
      contact_id: c.contact_id,
      contact_name: c.contact_name,
      from_stage: c.stage,
      days_since_activity: Math.floor((Date.now() - last) / (24 * 3600 * 1000)),
      last_activity_at: new Date(last).toISOString(),
    } });
  }
}
return out;

